315	    @Override
316	    @Transactional(readOnly = true)
317	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
318	        LocalDate businessDay = toBusinessDay(LocalDate.now());
319	        long registeredToday = ownerRepository.findAll().stream()
320	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
321	            .count();
322	        return registeredToday >= DAILY_CAPACITY;
323	    }
324	
325	    /**
326	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
327	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
328	     * registration date (whether supplied or defaulted to the server date) so that the stored
329	     * {@code registrationDate}, every value derived from it (such as the membership number's year
330	     * segment) and the per-day create-limit all use the adjusted business day.
331	     */
332	    private static LocalDate toBusinessDay(LocalDate date) {
333	        DayOfWeek day = date.getDayOfWeek();
334	        if (day == DayOfWeek.SATURDAY) {
335	            return date.plusDays(2);
336	        }
337	        if (day == DayOfWeek.SUNDAY) {
338	            return date.plusDays(1);
339	        }
340	        return date;
341	    }
