343	    @Override
344	    @Transactional(readOnly = true)
345	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
346	        String normalized = normalizeTelephone(telephone);
347	        if (normalized == null) {
348	            return false;
349	        }
350	        return ownerRepository.findAll().stream()
351	            .map(owner -> normalizeTelephone(owner.getTelephone()))
352	            .anyMatch(normalized::equals);
353	    }
354	
355	    @Override
356	    @Transactional(readOnly = true)
357	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
358	        String normalizedLastName = normalizeHouseholdValue(lastName);
359	        String normalizedAddress = normalizeHouseholdAddress(address);
360	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
361	            return false;
362	        }
363	        return ownerRepository.findAll().stream()
364	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
365	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
366	    }
367	
368	    @Override
369	    @Transactional(readOnly = true)
370	    public String householdIdFor(String lastName, String address) throws DataAccessException {
371	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
372	        try {
373	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
374	            StringBuilder sb = new StringBuilder(32);
375	            for (int i = 0; i < 8; i++) {
376	                sb.append(String.format("%02X", digest[i]));
377	            }
378	            return sb.toString();
379	        } catch (NoSuchAlgorithmException ex) {
380	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
381	        }
382	    }
383	
384	    /**
385	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
386	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
387	     * spaced but equivalent values compare equal.
388	     */
389	    private static String normalizeHouseholdValue(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
394	    }
395	
396	    /**
397	     * Normalizes an address for household comparison by first applying the canonical address
398	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
399	     * then the shared household-value normalization, so every address comparison uses the same
400	     * normalized form regardless of how the value was originally supplied.
401	     */
402	    private static String normalizeHouseholdAddress(String address) {
403	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
404	    }
405	
406	    /**
407	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
408	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
409	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
410	     */
411	    private static String normalizeTelephone(String telephone) {
412	        if (telephone == null) {
413	            return null;
414	        }
415	        try {
416	            return TelephoneNormalizer.toE164(telephone);
417	        } catch (InvalidTelephoneException ex) {
418	            return telephone.replaceAll("\\D", "");
419	        }
420	    }
