440	    private <T> T findEntityById(Supplier<T> supplier) {
441	        try {
442	            return supplier.get();
443	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
444	            // Just ignore not found exceptions for Jdbc/Jpa realization
445	            return null;
446	        }
447	    }
